import pandas as pd, collections

def top_levels(path):
    return path.split('>')[0].strip()

for f in ['amazon_product_categories.csv','fb_product_categories.csv','google_shopping_product_categories.csv']:
    df=pd.read_csv('/root/data/'+f)
    cnt=collections.Counter(df['category_path'].map(top_levels))
    print('\n',f, 'top level unique', len(cnt))
    for name,count in cnt.most_common(20):
        print(name, count)
